# run_all_experiments.ps1
# This script runs all Chronos experiment configurations generated by the preparation script.

$ConfigDir = "scripts/traffic_experiment_extended/configs"
$PythonBin = "./venv/Scripts/python.exe"

# Verification
if (-not (Test-Path $PythonBin)) {
    Write-Error "Python interpreter not found at $PythonBin"
    return
}

if (-not (Test-Path "scripts/chronos_experiment")) {
    Write-Error "This script must be run from the project root directory."
    return
}

# Find all YAML configs
$Configs = Get-ChildItem -Path $ConfigDir -Filter *.yaml

if ($null -eq $Configs -or $Configs.Count -eq 0) {
    Write-Host "No configuration files found in $ConfigDir" -ForegroundColor Yellow
    Write-Host "Did you run scripts/prepare_traffic_experiment_2.py first?"
    return
}

Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "Starting Chronos Experiment Suite" -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan

foreach ($ConfigFile in $Configs) {
    $Path = $ConfigFile.FullName
    Write-Host ""
    Write-Host ">>> Current Experiment: $($ConfigFile.Name)" -ForegroundColor Green
    Write-Host "----------------------------------------------------------"
    
    # Run the experiment
    & $PythonBin -m scripts.chronos_experiment.cli --config "$Path"
    
    # Check exit status
    if ($LASTEXITCODE -ne 0) {
        Write-Host "!!! Warning: Experiment failed for $($ConfigFile.Name). Continuing to next..." -ForegroundColor Red
    } else {
        Write-Host ">>> Completed $($ConfigFile.Name) successfully." -ForegroundColor Green
    }
    Write-Host "----------------------------------------------------------"
}

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "All experiments complete!" -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan
